animationCss:
#manual-mode .mm-order{animation:mm-order 12s ease-in-out infinite;}
#manual-mode .mm-receipt{animation:mm-receipt 12s ease-in-out infinite;}
#manual-mode .mm-check{animation:mm-check 12s ease-in-out infinite;}
#manual-mode .mm-review-scan{animation:mm-review-scan 10s ease-in-out infinite;}
#manual-mode .mm-review-check{animation:mm-review-check 10s ease-in-out infinite;}
#manual-mode .mm-review-check.b{animation-delay:.55s;}
#manual-mode .mm-review-check.c{animation-delay:1.1s;}
#manual-mode .mm-score-packet{stroke-dasharray:12 190;animation:mm-packet 9s linear infinite;}
#manual-mode .mm-phone-one{animation:mm-phone-one 9s steps(1,end) infinite;}
#manual-mode .mm-phone-zero{animation:mm-phone-zero 9s steps(1,end) infinite;}
#manual-mode .mm-screen-one{animation:mm-screen-one 9s steps(1,end) infinite;}
#manual-mode .mm-screen-zero{animation:mm-screen-zero 9s steps(1,end) infinite;}
#manual-mode .mm-flow-line{stroke-dasharray:45 190;animation:mm-flow 9s ease-in-out infinite;}
#manual-mode .mm-headlight{animation:mm-headlight 12s ease-in-out infinite;}
#manual-mode .mm-road-pulse{stroke-dasharray:90 700;animation:mm-road 12s ease-in-out infinite;}
#manual-mode[data-paused='true'] *,#manual-mode[data-paused='true'] *::before,#manual-mode[data-paused='true'] *::after{animation-play-state:paused!important;}
@keyframes mm-order{0%,12%{transform:translate(0,0);opacity:0}17%,29%{transform:translate(0,0);opacity:1}46%,56%{transform:translate(164px,-16px);opacity:1}62%,100%{transform:translate(164px,-16px);opacity:0}}
@keyframes mm-receipt{0%,43%{transform:translateY(-19px);opacity:0}53%,76%{transform:translateY(0);opacity:1}85%,100%{opacity:0}}
@keyframes mm-check{0%,56%{opacity:.1}62%,79%{opacity:1}87%,100%{opacity:.1}}
@keyframes mm-review-scan{0%,12%{transform:translateY(0);opacity:0}17%{opacity:.8}46%{transform:translateY(48px);opacity:.8}53%,100%{transform:translateY(48px);opacity:0}}
@keyframes mm-review-check{0%,44%{opacity:.12}52%,78%{opacity:1}88%,100%{opacity:.12}}
@keyframes mm-packet{0%,20%{stroke-dashoffset:12;opacity:0}23%{opacity:1}46%{stroke-dashoffset:-130;opacity:1}50%,100%{stroke-dashoffset:-130;opacity:0}}
@keyframes mm-phone-one{0%,20%,89%,100%{opacity:0}21%,88%{opacity:1}}
@keyframes mm-phone-zero{0%,20%,89%,100%{opacity:1}21%,88%{opacity:0}}
@keyframes mm-screen-one{0%,46%,89%,100%{opacity:0}47%,88%{opacity:1}}
@keyframes mm-screen-zero{0%,46%,89%,100%{opacity:1}47%,88%{opacity:0}}
@keyframes mm-flow{0%{stroke-dashoffset:0}100%{stroke-dashoffset:-235}}
@keyframes mm-headlight{0%,12%,86%,100%{opacity:.16}21%,75%{opacity:.9}}
@keyframes mm-road{0%,17%{stroke-dashoffset:0;opacity:0}23%{opacity:.7}72%{stroke-dashoffset:730;opacity:.7}80%,100%{stroke-dashoffset:730;opacity:0}}

@media(prefers-reduced-motion:reduce){#manual-mode *,#manual-mode *::before,#manual-mode *::after{animation:none!important;}#manual-mode .mm-order,#manual-mode .mm-score-packet,#manual-mode .mm-phone-one,#manual-mode .mm-screen-one,#manual-mode .mm-road-pulse{opacity:0;}#manual-mode .mm-receipt,#manual-mode .mm-phone-zero,#manual-mode .mm-screen-zero{opacity:1;}}
